/** The control for get_shopping_list: See what's on your shopping list. */
@Composable
fun GetShoppingListButton(
    input: GetShoppingListInput,
    modifier: Modifier = Modifier,
    text: String = GetShoppingListAction.LABEL,
    tone: OuroTone = OuroTone.Primary,
    variant: OuroButtonVariant = OuroButtonVariant.Solid,
    size: OuroButtonSize = OuroButtonSize.Md,
    enabled: Boolean = true,
    onResult: (Result<GetShoppingListOutput>) -> Unit = {},
) {
    val scope = rememberCoroutineScope()
    OuroButton(
        text = text,
        onClick = { scope.launch { onResult(runCatching { GetShoppingListAction.run(input) }) } },
        modifier = modifier.ouroAction(GetShoppingListAction.ID, GetShoppingListAction.consent.wire, GetShoppingListAction.DESCRIPTION),
        tone = tone,
        variant = variant,
        size = size,
        enabled = enabled,
    )
}

